from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)

        # Build prefix sums: prefix[i] is the sum of nums[0...i-1]
        prefix = [0] * (n + 1)
        for i, x in enumerate(nums, 1):
            prefix[i] = prefix[i - 1] + x

        neg_inf = -10**18

        # prev[i] stores the max sum of `used - 1` subarrays in the prefix of length `i`
        # Using 0 subarrays yields a max sum of 0
        prev = [0] * (n + 1)

        for used in range(1, k + 1):
            curr = [neg_inf] * (n + 1)
            best_start = neg_inf

            # A valid configuration of `used` arrays of length `m` requires at least `used * m` elements.
            for i in range(used * m, n + 1):
                start = i - m

                # Check if it's possible to form `used - 1` valid subarrays in the first `start` elements
                if prev[start] != neg_inf:
                    diff = prev[start] - prefix[start]
                    if diff > best_start:
                        best_start = diff

                c = curr[i - 1]

                # If we have a valid starting point, evaluate the new sum ending exactly at/before `i`
                if best_start != neg_inf:
                    val = prefix[i] + best_start
                    if val > c:
                        curr[i] = val
                    else:
                        curr[i] = c
                else:
                    curr[i] = c

            # Move current DP states to previous for the next subarray count
            prev = curr

        return prev[n]
